const inputHelp={
price:'Der reine Kaufpreis ohne Nebenkosten. Ein höherer Preis erhöht Kapitalbedarf, Kredit und meist auch die Grundlage der Abschreibung.',
equity:'Dein eigenes Geld für Kauf, Nebenkosten und Renovierung. Mehr Eigenkapital bedeutet weniger Kredit und niedrigere Raten. Die Auto-Buttons setzen einmalig 10 oder 20 % nur des Kaufpreises ein; du kannst den Betrag danach frei ändern.',
initialRenovation:'Einmalige Arbeiten beim Kauf. Sie erhöhen den Geldbedarf. Die gewählte steuerliche Art entscheidet, wann du die Kosten absetzen kannst.',
buildingShare:'Vom Kaufpreis entfällt ein Teil auf das Gebäude und ein Teil auf Grund und Boden. Nur das Gebäude wird abgeschrieben. Beispiel: 300.000 € × 60 % = 180.000 € Gebäudewert vor Nebenkosten. Ein höherer Gebäudeanteil erhöht die AfA und senkt meist die Einkommensteuer. Den zulässigen Anteil anhand der GrundanteilV oder eines Nachweises bestimmen; nicht frei zur Steueroptimierung wählen.',
afa:'AfA heißt Abschreibung: Ein Teil der Gebäudekosten wird jedes Jahr vom steuerlichen Mietergebnis abgezogen, obwohl du dafür kein Geld neu ausgibst. Bei 180.000 € Gebäudebasis und 1,5 % sind das 2.700 € pro Jahr. Das ist ein Abzug vom Einkommen, keine Erstattung von 2.700 €.',
otherTaxable:'Dein jährliches steuerpflichtiges Einkommen ohne diese Vermietung, z. B. aus dem Gehalt nach steuerlichen Abzügen. Es ist nicht dein Brutto- oder Nettogehalt. Es bestimmt, wie stark ein Mietgewinn oder anerkannter Mietverlust deine Einkommensteuer verändert.',
lossOffset:'Bei anerkannten Vermietungsverlusten kann die Einkommensteuer auf anderes Einkommen im selben Jahr sinken. Das kann eine Erstattung ergeben. Ohne ausreichende Steuerbelastung entsteht keine entsprechende Auszahlung. Liebhaberei und Ausgleichsbeschränkungen beachten.',
rate:'Der jährliche Kreditzins. Ein höherer Zinssatz erhöht die Rate und die abzugsfähigen Zinsen. Die Rückzahlung des Kredits selbst ist nicht steuerlich abzugsfähig.',
yearsLoan:'Zeitraum bis zur geplanten vollständigen Rückzahlung. Eine längere Laufzeit senkt meist die Monatsrate, erhöht aber die gesamten Zinskosten.',
horizon:'So viele Jahre vergleichst du Immobilie und ETF. Am Ende wird ein Verkauf mit Schuldenabzug und Steuer unterstellt.',
operating:'Kosten, die du als Vermieter selbst trägst und nicht an Mieter weitergibst. Sie senken Cashflow und grundsätzlich auch das steuerliche Ergebnis.',
otherIncome:'Zusätzliche Einnahmen neben dem Hauptmietzins. Sie erhöhen Cashflow und Steuergewinn. Im MRG-Fall müssen sie eigenständig zulässig sein.',
vacancy:'Geschätzter Anteil der Miete, der durch Leerstand oder Ausfälle fehlt. 5 % bedeutet, dass nur 95 % der geplanten Einnahmen angesetzt werden.',
annualExtra:'Weitere tatsächlich anfallende, sofort abzugsfähige Vermietungskosten. Sie senken Geldüberschuss und Steuergewinn. Keine bereits anderswo erfassten Beträge doppelt ansetzen.',
appreciation:'Angenommene jährliche Änderung des Immobilienwerts. Sie beeinflusst Verkaufserlös und ImmoESt, bringt während der Vermietung aber kein Geld auf dein Konto.',
costGrowth:'So stark wachsen die laufenden Ausgaben jedes Jahr. Höhere Kostensteigerungen reduzieren künftige Überschüsse.',
etfReturn:'Erwartete Gesamtrendite pro Jahr inklusive Dividenden und Wiederanlage, vor persönlicher Steuer. Ein höherer Wert erhöht die ETF-Prognose. Historische Indexrenditen sind eine Orientierung, keine Prognose.',
etfTax:'KESt auf die im vereinfachten Modell berücksichtigten ETF-Erträge. Standard 27,5 %. Net Return eines Index bedeutet nach Quellensteuer, nicht nach deiner österreichischen KESt.',
startYear:'Kalenderjahr des Kaufs. Das Modell nimmt Kauf und steuerliche Vermietungsbereitschaft ab Januar an. Das Mietvertragsdatum kann die ersten Mieteinnahmen nach hinten verschieben.'
};
function showInputHelp(button,text){let tip=$('inputHelpTooltip');if(!tip){tip=document.createElement('div');tip.id='inputHelpTooltip';tip.className='input-help-tooltip';tip.setAttribute('role','tooltip');document.body.append(tip)}tip.textContent=text;tip.hidden=false;const b=button.getBoundingClientRect();tip.style.left=Math.max(12,Math.min(innerWidth-tip.offsetWidth-12,b.left))+'px';const below=b.bottom+8;tip.style.top=(below+tip.offsetHeight<innerHeight-12?below:Math.max(12,b.top-tip.offsetHeight-8))+'px';}
function hideInputHelp(){const tip=$('inputHelpTooltip');if(tip)tip.hidden=true;}
function field(key,label,unitOrOptions,hint,obj,onchange){const div=document.createElement('div');div.className='field';const lab=document.createElement('label');lab.htmlFor='f-'+key;lab.innerHTML=label+(typeof unitOrOptions==='string'?` <span>(${unitOrOptions})</span>`:'');let input;if(Array.isArray(unitOrOptions)){input=document.createElement('select');for(const [value,name]of unitOrOptions){const o=document.createElement('option');o.value=value;o.textContent=name;input.append(o)}}else{input=document.createElement('input');input.type=unitOrOptions==='Datum'?'date':'number';input.step='any';if(!['rentGrowth','costGrowth','appreciation','etfReturn','rentShift','rateShift','vacancyShift','costShift','valueShift','inflationForecast'].includes(key))input.min='0';if(['vacancy','buildingShare','immoTax','etfTax'].includes(key))input.max='100';if(key==='horizon')input.max='50';}input.id='f-'+key;input.value=obj[key];input.setAttribute('aria-label',label);input.addEventListener(input.type==='number'?'input':'change',()=>{const v=input.type==='number'?Number(input.value):input.value;if(input.value===''&&input.type!=='date'||!Number.isFinite(v)&&input.type==='number'){return}obj[key]=v;onchange();});input.addEventListener('blur',()=>{input.value=obj[key]});const name=document.createElement('div');name.className='field-name';name.append(lab);const explanation=inputHelp[key]||hint;if(explanation){const info=document.createElement('button');info.type='button';info.className='input-help';info.textContent='i';info.setAttribute('aria-label','Info: '+label);info.setAttribute('aria-describedby','inputHelpTooltip');info.onpointerenter=()=>showInputHelp(info,explanation);info.onpointerleave=hideInputHelp;info.onfocus=()=>showInputHelp(info,explanation);info.onblur=hideInputHelp;info.onclick=()=>showInputHelp(info,explanation);name.append(info)}div.append(name,input);if(key==='equity'){const shortcuts=document.createElement('div');shortcuts.className='equity-shortcuts';const caption=document.createElement('span');caption.textContent='Auto aus Kaufpreis:';shortcuts.append(caption);for(const pct of [10,20]){const b=document.createElement('button');b.type='button';b.className='outline';b.textContent=pct+' %';b.setAttribute('aria-label','Eigenkapital auf '+pct+' % des Kaufpreises setzen');b.onclick=()=>{obj.equity=Math.round(obj.price*pct)/100;input.value=obj.equity;onchange()};shortcuts.append(b)}div.append(shortcuts)}return div;}
function renderInputs(){const root=$('inputGroups');root.innerHTML='';for(const [label,fields]of groups){if(label==='Vermietung & Ausgaben')continue;const div=document.createElement('div');div.className='group';const h=document.createElement('h3');h.textContent=label;div.append(h);for(const f of fields){const item=field(f[0],f[1],f[2],f[3],s,()=>{Object.assign(s,normalize(s));save();update()});if(f[0]==='etfReturn'){const info=document.createElement('button');info.type='button';info.className='info-button';info.textContent='ⓘ Historische Indexrenditen';info.onclick=openEtfInfo;item.append(info)}div.append(item)}if(label==='Steuerannahmen · private Vermietung AT'){const note=document.createElement('p');note.className='note tax-explainer';note.id='taxReliefInfo';div.append(note)}root.append(div)}renderRentalInputs()}
function kp(id,data){$(id).innerHTML=data.map(([label,value,sub])=>`<div class="kpi"><label>${label}</label><strong>${value}</strong><small>${sub}</small></div>`).join('')}
function table(id,columns,rows){const sort=sorts[id];let ordered=[...rows];if(sort)ordered.sort((a,b)=>typeof a[sort.key]==='number'?(a[sort.key]-b[sort.key])*sort.dir:String(a[sort.key]).localeCompare(String(b[sort.key]),'de')*sort.dir);$(id).innerHTML='<thead><tr>'+columns.map(c=>`<th scope="col" aria-sort="${sort?.key===c.key?(sort.dir===1?'ascending':'descending'):'none'}"><button data-sort="${c.key}">${c.label} ${sort?.key===c.key?(sort.dir===1?'↑':'↓'):'↕'}</button></th>`).join('')+'</tr></thead><tbody>'+ordered.map(r=>'<tr>'+columns.map(c=>`<td class="${c.key==='afterTax'||c.key==='difference'?(r[c.key]>=0?'positive':'negative'):''}">${c.format?c.format(r[c.key],r):r[c.key]}</td>`).join('')+'</tr>').join('')+'</tbody>';$(id).querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{sorts[id]={key:b.dataset.sort,dir:sort?.key===b.dataset.sort?-sort.dir:1};table(id,columns,rows)})}
const col=(key,label,money=true)=>({key,label,format:money?eur:undefined});
function chart(id,rows,series,type='line'){const root=$(id);if(!root||!rows.length)return;const w=900,h=310,L=90,R=20,T=55,B=40,iw=w-L-R,ih=h-T-B;const values=rows.flatMap(r=>series.map(z=>r[z.key]));let min=Math.min(0,...values),max=Math.max(0,...values);if(max===min)max=min+1;const gap=(max-min)*.08;min-=gap;max+=gap;const x=i=>L+iw*(i+.5)/rows.length,y=v=>T+ih*(max-v)/(max-min),bar=iw/rows.length*.68;let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${root.parentElement.querySelector('h3')?.textContent||'Diagramm'}"><title>Werte mit Maus, Berührung oder Tabulatortaste anzeigen</title>`;for(let i=0;i<=4;i++){const v=max-(max-min)*i/4,yy=y(v);svg+=`<line x1="${L}" x2="${w-R}" y1="${yy}" y2="${yy}" stroke="#e6ecf3"/><text x="${L-9}" y="${yy+4}" text-anchor="end">${eur(v)}</text>`}svg+=`<line x1="${L}" x2="${w-R}" y1="${y(0)}" y2="${y(0)}" stroke="#9baec2"/>`;series.forEach((z,zi)=>{if(type==='bar'){rows.forEach((r,i)=>{const v=r[z.key],xx=x(i)-bar/2+zi*bar/series.length,yy=y(v);svg+=`<rect x="${xx}" y="${Math.min(y(0),yy)}" width="${bar/series.length}" height="${Math.max(1,Math.abs(yy-y(0)))}" rx="2" fill="${v<0?RED:z.color}"/>`})}else svg+=`<polyline fill="none" stroke="${z.color}" stroke-width="3" points="${rows.map((r,i)=>x(i)+','+y(r[z.key])).join(' ')}"/>`;});rows.forEach((r,i)=>{const tip=(r.label||'Jahr '+r.year+(r.calendar?' · '+r.calendar:''))+'\n'+series.map(z=>z.name+': '+eur(r[z.key])).join('\n');svg+=`<rect class="hit" data-index="${i}" tabindex="0" aria-label="${tip.replaceAll('\n','; ')}" x="${L+iw*i/rows.length}" y="${T}" width="${iw/rows.length}" height="${ih}" fill="transparent"><title>${tip}</title></rect>`;if(rows.length<=10||i%Math.ceil(rows.length/7)===0||i===rows.length-1)svg+=`<text x="${x(i)}" y="${h-13}" text-anchor="middle">${r.label||r.year+'. J.'}</text>`});svg+='</svg>';root.innerHTML='<div class="legend">'+series.map(z=>`<span><i style="background:${z.color}"></i>${z.name}</span>`).join('')+'</div>'+svg;root.querySelectorAll('.hit').forEach(hit=>{function show(ev){const r=rows[+hit.dataset.index],tip=$('tooltip');tip.textContent=(r.label||`Jahr ${r.year}${r.calendar?' · '+r.calendar:''}`)+'\n'+series.map(z=>`${z.name}: ${eur(r[z.key])}`).join('\n');tip.hidden=false;const rect=hit.getBoundingClientRect(),xx=ev.clientX||rect.x+rect.width/2,yy=ev.clientY||rect.y;tip.style.left=Math.max(8,Math.min(innerWidth-tip.offsetWidth-10,xx+12))+'px';tip.style.top=Math.max(8,Math.min(innerHeight-tip.offsetHeight-10,yy+12))+'px'}hit.onpointermove=show;hit.onpointerdown=show;hit.onfocus=show;hit.onpointerleave=()=>{$('tooltip').hidden=true};hit.onblur=()=>{$('tooltip').hidden=true};});}
function cashDetails(){const q=results.rows[Math.min(detailYear,results.rows.length)-1],d=unit==='month'?12:1;const year=q.year;$('bridgeLabel').textContent=`Jahr ${year} · ${q.calendar} · ${unit==='month'?'monatlicher Durchschnitt':'Jahresbeträge'}`;const items=[['Miete',q.income],['Betriebskosten',-q.operating],['Rücklage',-q.reserve],['Erhaltung',-q.maintenance-q.extra-q.shock],['Zinsen',-q.interest],['Tilgung',-q.principal],['ESt',-q.taxEffect],['Übrig',q.afterTax]];chart('cashBridge',items.map(([label,v])=>({label,amount:v/d})),[{key:'amount',name:unit==='month'?'Betrag pro Monat':'Betrag pro Jahr',color:BLUE}],'bar');const lines=[['Miete nach Leerstand',q.income],['Abzugsfähige Ausgaben',-q.operating-q.maintenance-q.extra-q.shock],['Kreditzinsen',-q.interest],['Gebäude-AfA',-q.dep],['Renovierungsabzug',-q.renovationDed],['Steuerliches Ergebnis',q.taxable],['Zusätzliche ESt / Entlastung (−)',q.taxEffect]];$('taxBridge').innerHTML='<div class="ledger">'+lines.map(([k,v])=>`<div><span>${k}</span><strong>${eur(v/d)}</strong></div>`).join('')+'</div><p class="note">Tilgung und WEG-Einzahlungen mindern den Cashflow, aber nicht den Steuergewinn. AfA mindert den Steuergewinn ohne laufenden Geldabfluss.</p>';table('monthlyTable',[col('month','Monat',false),{key:'contractRent',label:'Hauptmietzins',format:eur2},{key:'rentCap',label:'Mietzinsgrenze',format:v=>v===null?'Keine 15h-Grenze':eur2(v)},col('income','Einnahmen'),col('pay','Kreditrate'),col('taxEffect','ESt (geglättet)'),col('shock','Sonderaufwand'),col('afterTax','Netto-Cashflow'),col('contribution','Zuschuss'),col('debt','Restschuld')],results.months.filter(r=>r.year===year));}
function breakEvenRent(p){if(run({...p,rent:0}).first.afterTax>=0)return 0;if(run({...p,rent:100000}).first.afterTax<0)return null;let lo=0,hi=100000;for(let i=0;i<35;i++){let mid=(lo+hi)/2;if(run({...p,rent:mid}).first.afterTax>=0)hi=mid;else lo=mid}return hi;}
function shifted(p,c){return normalize({...p,rent:p.rent*(1+c.rentShift/100),rate:p.rate+c.rateShift,vacancy:p.vacancy+c.vacancyShift,operating:p.operating*(1+c.costShift/100),reserve:p.reserve*(1+c.costShift/100),maintenance:p.maintenance*(1+c.costShift/100),annualExtra:p.annualExtra*(1+c.costShift/100),appreciation:p.appreciation+c.valueShift,shockCost:c.shockCost||0,shockYear:c.shockYear||10})}
function scenarios(){const p=results.p,base=results,br=breakEvenRent(p),first=base.rows.find(r=>r.afterTax>=0);kp('scenarioKpis',[['Cashflow-neutrale Nettomiete',br===null?'Nicht erreichbar':eur(br),br===null&&p.rentalMode!=='market'?'Im 1. Jahr innerhalb der Mietzinsgrenze nicht erreichbar':'Im 1. Jahr bei unveränderten übrigen Annahmen'],['Erstes positives Cashflow-Jahr',first?'Jahr '+first.year:'Keines','Innerhalb des gewählten Horizonts'],['Zusätzlicher Kapitalbedarf',eur(base.last.external-base.equity),'Nach Nutzung angesammelter Überschüsse'],['Schlechtestes Cashflow-Jahr',eur(Math.min(...base.rows.map(q=>q.afterTax))/12),'Monatlicher Jahresdurchschnitt']]);const sets=[{name:'Basis',r:base,color:BLUE},{name:'Vorsichtig',r:run(shifted(p,{rentShift:-10,rateShift:1.5,vacancyShift:5,costShift:15,valueShift:-1})),color:RED},{name:'Günstig',r:run(shifted(p,{rentShift:10,rateShift:-.5,vacancyShift:-2,costShift:-5,valueShift:1})),color:GREEN},{name:'Eigenes Szenario',r:run(shifted(p,custom)),color:AMBER}];table('scenarioTable',[col('name','Szenario',false),{key:'rent',label:'Angesetzte Miete · Start',format:eur2},{key:'rate',label:'Zins',format:v=>num(v)+' %'},col('cash','CF / Monat · Jahr 1'),col('external','Zusätzliche Einzahlungen'),col('wealth','Immo netto · Ende'),col('etf','ETF netto · Ende'),col('difference','Vorteil Immo')],sets.map(z=>({name:z.name,rent:z.r.rental.initialRent,rate:z.r.p.rate,cash:z.r.first.afterTax/12,external:z.r.last.external-z.r.equity,wealth:z.r.last.propertyNet,etf:z.r.last.etfNet,difference:z.r.last.difference})));chart('scenarioChart',base.rows.map((r,i)=>Object.assign({year:r.year,calendar:r.calendar},...sets.map((z,j)=>({['s'+j]:z.r.rows[i].propertyNet})))),sets.map((z,j)=>({key:'s'+j,name:z.name,color:z.color})));heatmap();}
const axes={rent:{label:'Miete',steps:[-20,-10,0,10,20],unit:'%',apply:(p,v)=>({...p,rent:p.rent*(1+v/100)})},price:{label:'Kaufpreis',steps:[-20,-10,0,10,20],unit:'%',apply:(p,v)=>({...p,price:p.price*(1+v/100)})},appreciation:{label:'Wertsteigerung',steps:[-2,-1,0,1,2],unit:'%-Pkt.',apply:(p,v)=>({...p,appreciation:p.appreciation+v})},vacancy:{label:'Leerstand',steps:[-4,-2,0,2,4],unit:'%-Pkt.',apply:(p,v)=>({...p,vacancy:p.vacancy+v})},rate:{label:'Zins',steps:[-2,-1,0,1,2],unit:'%-Pkt.',apply:(p,v)=>({...p,rate:p.rate+v})},etfReturn:{label:'ETF-Rendite',steps:[-2,-1,0,1,2],unit:'%-Pkt.',apply:(p,v)=>({...p,etfReturn:p.etfReturn+v})},costs:{label:'Kosten',steps:[-20,-10,0,10,20],unit:'%',apply:(p,v)=>shifted(p,{rentShift:0,rateShift:0,vacancyShift:0,costShift:v,valueShift:0})}};
function heatmap(){const ya=axes[$('axisY').value],xa=axes[$('axisX').value],metric=$('heatMetric').value,label=(a,v)=>`${v>0?'+':''}${v} ${a.unit}`;let html=`<table class="heat"><thead><tr><th>${ya.label} / ${xa.label}</th>`+xa.steps.map(v=>`<th>${label(xa,v)}</th>`).join('')+'</tr></thead><tbody>';for(const yy of ya.steps){html+=`<tr><th scope="row">${label(ya,yy)}</th>`;for(const xx of xa.steps){const r=run(xa.apply(ya.apply(results.p,yy),xx)),value=metric==='cash'?r.first.afterTax/12:metric==='wealth'?r.last.propertyNet:r.last.difference;html+=`<td class="${value>=0?'heat-positive':'heat-negative'} ${xx===0&&yy===0?'baseline':''}" title="Angesetzte Startmiete ${eur(r.rental.initialRent)} · Zins ${num(r.p.rate)} % · Leerstand ${num(r.p.vacancy)} %">${eur(value)}</td>`}html+='</tr>'}$('heatmap').innerHTML=html+'</tbody></table>';}
function update(){results=run(s);rentalStatus();const r=results,last=r.last;const taxInfo=$('taxReliefInfo');if(taxInfo)taxInfo.textContent='Steuerwirkung im 1. Jahr: Gebäude-AfA '+eur2(r.first.dep)+' · '+(r.first.taxEffect<0?'mögliche ESt-Entlastung '+eur2(-r.first.taxEffect):'zusätzliche Einkommensteuer '+eur2(r.first.taxEffect))+'. Der Kauf allein löst keine jährliche Steuererstattung aus. Die AfA senkt das steuerpflichtige Mietergebnis; nur ein insgesamt anerkannter Verlust kann über anderes Einkommen zu einer Erstattung führen. Diese Wirkung ist bereits im Cashflow enthalten und darf nicht nochmals addiert werden.';$('horizonTag').textContent=r.p.horizon;$('validation').textContent=s.equity>r.upfront?'Es werden nur '+eur(r.upfront)+' Eigenkapital eingesetzt. Der übrige Betrag bleibt in beiden Alternativen außerhalb des Vergleichs.':'';kp('kpis',[['Immobilie netto',eur(last.propertyNet),'Verkauf + angesammelte Überschüsse'],['ETF netto',eur(last.etfNet),'Vereinfachte Ausschüttungs- und Verkaufssteuer'],['Cashflow / Monat',eur(r.first.afterTax/12),'Durchschnitt im 1. Jahr nach Steuer'],['Vorteil Immobilie',eur(last.difference),'Bei gleichen externen Einzahlungen']]);const prob=run({...r.p,horizon:25}).last.taxableTotal;$('taxStatus').textContent=`Steuerpflichtiges Ergebnis im 1. Jahr: ${eur(r.first.taxable)} · ESt-Wirkung: ${eur(r.first.taxEffect)}. ${prob<0?'Prüfhinweis: kumuliertes Vermietungsergebnis nach 25 Jahren negativ; Verlustausgleich nicht gesichert.':'25-Jahres-Modellindikator: kumuliertes Vermietungsergebnis positiv; keine verbindliche Liebhabereiprüfung.'}`;kp('cashKpis',[['Kreditrate / Monat',eur(r.payment),'Zins und Tilgung zusammen'],['Zinsen insgesamt',eur(r.rows.reduce((a,q)=>a+q.interest,0)),'Über den gewählten Horizont'],['Zusätzlicher Zuschuss',eur(last.external-r.equity),'Nach Aufbrauchen des Cash-Guthabens'],['Restschuld am Ende',eur(last.debt),'Nach '+r.p.horizon+' Jahren']]);kp('compareKpis',[['Startkapital',eur(r.equity),'In beiden Varianten gleich'],['Externe Einzahlungen gesamt',eur(last.external),'Startkapital plus Zuschüsse'],['Immo-Verkaufsteuer',eur(last.saleTax),'AfA-Korrektur berücksichtigt'],['ETF-Steuern gesamt',eur(last.etfTaxPaid+last.etfSaleTax),'Laufend + hypothetischer Verkauf']]);detailYear=Math.min(detailYear,r.rows.length);$('detailYear').innerHTML=r.rows.map(q=>`<option value="${q.year}" ${q.year===detailYear?'selected':''}>Jahr ${q.year} · ${q.calendar}</option>`).join('');table('cfTable',[col('year','Jahr',false),col('calendar','Kalender',false),{key:'contractRent',label:'Hauptmietzins / Monat Ø',format:eur2},col('income','Einnahmen nach Ausfall'),col('costs','Laufende Ausgaben'),col('interest','Zinsen'),col('principal','Tilgung'),col('taxEffect','ESt (+) / Entlastung (−)'),col('afterTax','Netto-CF'),col('contributions','Zuschuss'),col('retained','Cash-Guthaben'),col('debt','Restschuld')],r.rows);table('compareTable',[col('year','Jahr',false),col('propertyNet','Immobilie netto'),col('etfNet','ETF netto'),col('difference','Vorteil Immo'),col('invested','Einzahlungen'),col('saleTax','ImmoESt'),col('annualEtfDividend','ETF-Barausschüttung'),col('annualEtfTax','KESt Ausschüttung'),col('etfSaleTax','KESt Verkauf'),col('etfBasis','ETF-Anschaffungskosten')],r.rows);const wealth=[{key:'propertyNet',name:'Immobilie netto',color:BLUE},{key:'etfNet',name:'ETF netto',color:GREEN}];chart('wealthChart',r.rows,wealth);chart('compareChart',r.rows,wealth);chart('cfChart',r.rows,[{key:'afterTax',name:'Cashflow nach Steuer',color:BLUE}],'bar');chart('debtChart',r.rows,[{key:'value',name:'Immobilienwert',color:BLUE},{key:'debt',name:'Restschuld',color:AMBER}]);chart('fullCFChart',r.rows,[{key:'afterTax',name:'Netto-Cashflow',color:BLUE},{key:'contributions',name:'Externer Zuschuss',color:AMBER}],'bar');cashDetails();scenarios();method();}
function method(){const r=results,q=r.first,z=r.last;const cards=[
['1 · Kauf und Kredit',`Zum Kaufpreis kommen die eingegebenen Anschaffungsnebenkosten und die Anfangsrenovierung. Davon ziehen wir das tatsächlich eingesetzte Eigenkapital ab. Der Rest wird als Kredit mit gleichbleibender Monatsrate finanziert.`,[['Gesamtbedarf',r.upfront],['Eigenkapital',r.equity],['Darlehen',r.loan],['Monatsrate',r.payment]]],
['2 · Was bleibt von der Miete?',`Die Miete folgt dem gewählten Vermietungsmodell. Im MRG-Fall begrenzen Wertsicherung und ggf. eine Mietzinsobergrenze die Einnahmen; Leerstand reduziert sie zusätzlich. Laufende Kosten, Rücklage, Erhaltung, Zinsen und Tilgung werden bezahlt. Danach ziehen wir zusätzliche Einkommensteuer ab oder rechnen eine mögliche Entlastung dazu. Die Tilgung spart Schulden, ist aber trotzdem ein Geldabfluss.`,[['Einnahmen · Jahr 1',q.income],['Ausgaben inkl. Kredit',q.costs+q.pay],['Zusätzliche ESt / Entlastung (−)',q.taxEffect],['Cashflow nach Steuer',q.afterTax]]],
['3 · AfA und Renovierung',`Nur der Gebäudeanteil wird abgeschrieben. Die Basis umfasst anteilige aktivierbare Kaufnebenkosten und vollständig aktivierten Herstellungsaufwand. Grund und Boden werden nicht abgeschrieben. Linear sind bei Wohnraumvermietung regelmäßig 1,5 % vorgesehen; abweichende Sätze brauchen passende Voraussetzungen. Beschleunigt bedeutet im Modell 3× im ersten und 2× im zweiten Jahr. Erweitert gilt 3× für die ersten drei Jahre, nur bei erfüllter Fertigstellungs- und Bronze-Voraussetzung. Die Gesamt-AfA ist auf die Basis begrenzt. Instandsetzung wird separat über 15 Jahre abgesetzt, sofortige Instandhaltung nur im ersten Jahr. Die Kosten werden in allen Varianten bereits beim Kauf bezahlt.`,[['AfA-Basis',r.basis],['AfA · Jahr 1',q.dep],['Renovierungsabzug · Jahr 1',q.renovationDed]]],
['4 · Einkommensteuer',`Einnahmen minus Werbungskosten, Zinsen, AfA und Renovierungsabzug ergeben den Steuergewinn. Rücklage und Tilgung zählen nicht als Werbungskosten. Wir berechnen die Tarifsteuer einmal mit und einmal ohne Vermietung; die Differenz ist die Steuerwirkung. Die 2026-Grenzen bleiben für die Prognose nominal konstant; der 55-%-Spitzensatz endet im Modell 2029. Absetzbeträge, Veranlagungsfreibetrag, Sonderausgaben und künftige Gesetzesänderungen sind nicht modelliert. Anderes Einkommen bleibt konstant. Ein Verlust entlastet nur im selben Jahr und nur soweit anderes Einkommen tatsächlich Steuer auslöst; kein Verlustvortrag. Du kannst diese Entlastung ausschalten.`,[['Steuerliches Ergebnis · Jahr 1',q.taxable],['Tarifdifferenz · Jahr 1',q.taxEffect]]],
['5 · Rücklage und Liebhaberei',`WEG-Einzahlungen werden sofort bezahlt, steuerlich aber erst bei passenden tatsächlichen Aufwendungen relevant. Solche späteren Verwendungen werden hier nicht automatisch modelliert und dürfen nicht doppelt als eigene Erhaltung angesetzt werden. Für eine kleine Vermietung mit Beginn ab 2024 ist grundsätzlich ein Gesamtüberschuss innerhalb von 25 Jahren ab Vermietungsbeginn, höchstens 28 Jahren ab ersten Aufwendungen zu prüfen. Unser 25-Jahres-Indikator ohne Verkauf ist nur ein Anhaltspunkt, keine Anerkennung des Verlustausgleichs. Der Verkaufserlös zählt darin nicht mit.`,[]],
['6 · Verkauf und Immobilienertragsteuer',`Das Modell gilt für einen steuerpflichtigen Neukauf im Privatvermögen. Die steuerlichen Anschaffungskosten bestehen aus Kaufpreis und aktivierbaren Kaufnebenkosten, plus aktiviertem Herstellungsaufwand bzw. noch nicht abgesetzter Instandsetzung, minus bereits berücksichtigter Gebäude-AfA. Vom Verkaufspreis ziehen wir diese angepassten Kosten und die Kosten der Mitteilung/Selbstberechnung ab. Auf einen positiven Gewinn fallen standardmäßig 30 % an. Übrige Verkaufskosten reduzieren das Geld am Konto, beim besonderen Steuersatz aber nicht pauschal den Steuergewinn. Keine automatische Erstattung bei Verkaufsverlusten, keine Hauptwohnsitzbefreiung, kein Altvermögen, keine Umwidmung oder Regelbesteuerungsoption. Die Restschuld reduziert den Verkaufserlös, nicht den steuerlichen Gewinn.`,[['Wert am Ende',z.value],['Angepasste Anschaffungskosten',z.adjustedAcquisition],['Steuerlicher Verkaufsgewinn',z.saleGain],['ImmoESt',z.saleTax],['Netto-Verkaufserlös nach Kredit',z.saleNet]]],
['7 · Fairer Vergleich mit dem ETF',`Positive Immobilien-Cashflows landen auf einem unverzinsten Guthabenkonto. Spätere Fehlbeträge werden zuerst daraus gedeckt. Nur wenn das Konto nicht reicht, ist eine zusätzliche Einzahlung nötig. Genau diese Einzahlung wird zum gleichen Zeitpunkt im ETF angelegt. Negative Cashflows werden daher nicht nochmals vom Immobilien-Endvermögen abgezogen. Die WEG-Rücklage ist kein frei verfügbares Guthaben und wird beim Verkauf nicht separat ausgezahlt. Beide Alternativen verwenden das gleiche Startkapital und die gleichen externen Beiträge.`,[['Externe Beiträge gesamt',z.external],['Verfügbares Immo-Cash-Guthaben',z.retained]]],
['8 · ETF: Ausschüttungen und Verkauf',`Es gibt keinen pauschalen 2-%-Steuersatz und keine automatische 2-%-Steuerbasis mehr. Die Gesamtrendite enthält Barausschüttungen bereits. Monatlich wird der angegebene Ausschüttungsanteil mit dem KESt-Satz (Standard 27,5 %) besteuert und netto wiederangelegt; die Wiederanlage erhöht die Anschaffungskosten. Bei Verkauf fällt KESt nur auf einen positiven verbleibenden Gewinn an. Ohne Barausschüttung wird hier nur der Verkauf besteuert. Das ist eine vereinfachte Vergleichsrechnung: Österreich besteuert bei Fonds auch ausschüttungsgleiche Erträge ohne Auszahlung. Diese sowie Quellensteueranrechnung und konkrete OeKB-Meldedaten sind nicht modelliert. Bei thesaurierenden ETFs kann die Steuerstundung dadurch zu günstig erscheinen. Alte 2-%-Eingaben werden beim Laden und Import ignoriert.`,[['Laufende ETF-Steuern gesamt',z.etfTaxPaid],['Fortgeführte Steuerbasis',z.etfBasis],['Steuer bei Endverkauf',z.etfSaleTax],['ETF netto',z.etfNet]]],
...rentalMethodCards(r),
['11 · Zeitplan und Grenzen',`Der modellierte Kauf erfolgt im Januar des Startjahres. Für die Einnahmen gilt das Datum des neuen Mietvertrags; ein späterer Beginn reduziert die Mieteinnahmen entsprechend. Es werden volle Kalenderjahre gerechnet, daher keine Halbjahres-AfA. Die jährliche Einkommensteuerwirkung wird für die Liquiditätsplanung auf die Monate verteilt. Inflation, Zinsbindung/Anschlussfinanzierung, Umsatzsteuer und Vorsteuer, Förderungen, unterjährige Kauf-/Verkaufszeitpunkte, steuerliche Sonderfälle und eine vollständige Liebhabereiprognose sind nicht abgebildet. Anfangsrenovierungen erhöhen nicht automatisch den Marktwert; den Zusammenhang musst du in deinen Annahmen berücksichtigen. Alle Szenarien nutzen dieselbe Rechenlogik.`,[]]
];$('methodContent').innerHTML=cards.map(([title,text,items])=>`<article class="panel method"><h2>${title}</h2><p>${text}</p>${items.length?'<div class="ledger">'+items.map(([k,v])=>`<div><span>${k}</span><strong>${eur(v)}</strong></div>`).join('')+'</div>':''}</article>`).join('')+`<article class="panel method"><h2>Quellen und Steuerstand</h2><p>AfA und Verlustausgleich geprüft am 26.10.2026; übrige Steuerquellen am 20.10.2026, Mietrechtsquellen am 22.10.2026. Regeln werden nicht automatisch aktualisiert.</p><ul>
<li><a href="https://www.bmf.gv.at/themen/steuern/arbeitnehmerveranlagung/steuertarif-steuerabsetzbetraege/steuertarif-steuerabsetzbetraege.html" target="_blank" rel="noopener">BMF · Einkommensteuertarif 2026</a></li>
<li><a href="https://www.bmf.gv.at/themen/steuern/immobilien-grundstuecke/vermietung-verpachtung/absetzung-fuer-abnutzung-bei-vuv.html" target="_blank" rel="noopener">BMF · AfA und beschleunigte AfA</a></li>
<li><a href="https://www.oesterreich.gv.at/de/themen/steuern_und_finanzen/immobilienertragsteuer/1/Seite.2420008" target="_blank" rel="noopener">BMF / oesterreich.gv.at · Angepasste Anschaffungskosten</a></li>
<li><a href="https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=10004570" target="_blank" rel="noopener">RIS · EStG, insbesondere §§ 16, 28, 30 und 30a</a></li>
<li><a href="https://www.bmf.gv.at/themen/steuern/fuer-unternehmen/einkommensteuer/verlustverwertung.html" target="_blank" rel="noopener">BMF · Verlustausgleich und fehlender Verlustvortrag bei Vermietung</a></li>
<li><a href="https://findok.bmf.gv.at/findok/volltext?segmentId=2a19c4fa-f445-4685-b352-3cb766c46d88" target="_blank" rel="noopener">BMF · Instandsetzung bei Wohngebäuden</a></li>
<li><a href="https://findok.bmf.gv.at/findok/volltext?segmentId=122eaa17-0686-406b-a344-bbd9e6886f01" target="_blank" rel="noopener">BMF · Liebhabereirichtlinien, 25-/28-Jahres-Zeitraum</a></li>
<li><a href="https://findok.bmf.gv.at/findok/volltext?segmentId=f6bebe28-8310-4cb0-a917-4e70e8d89541" target="_blank" rel="noopener">BMF · Investmentfonds und Anpassung der Anschaffungskosten</a></li><li><a href="https://www.ris.bka.gv.at/eli/bgbl/1979/139/A1P15h/NOR40244830" target="_blank" rel="noopener">RIS · WGG § 15h, Sondergrenze beim qualifizierten Genossenschaftskauf</a></li>
<li><a href="https://ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=10011509" target="_blank" rel="noopener">RIS · WGG § 39 Abs. 36, Antrag / Angebot als Übergangskriterium</a></li>
<li><a href="https://www.statistik.at/fileadmin/pages/2114/VOe_Richtwerte_Kategoriemieten_20260401.pdf" target="_blank" rel="noopener">Statistik Austria · Richtwerte ab 1.4.2026</a></li>
<li><a href="https://ris.bka.gv.at/eli/bgbl/i/2025/114/P1/NOR40274266" target="_blank" rel="noopener">RIS · MieWeG § 1, Wertsicherungsgrenzen</a></li>
<li><a href="https://www.oesterreich.gv.at/de/themen/bauen_und_wohnen/wohnen/3/Seite.210215" target="_blank" rel="noopener">oesterreich.gv.at · Befristungsdauer ab 2026</a></li>
<li><a href="https://www.ris.bka.gv.at/GeltendeFassung.wxe?Abfrage=Bundesnormen&Gesetzesnummer=10002531" target="_blank" rel="noopener">RIS · MRG § 16 Abs. 9, schriftliches Erhöhungsbegehren</a></li>
<li><a href="https://service.bmf.gv.at/Service/Allg/ivf/AusschErtr/_start_auswahl.asp" target="_blank" rel="noopener">BMF · Fondssteuerdaten / OeKB</a></li></ul></article>`;}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csv(){const cols=['year','calendar','contractRent','rentCap','income','operating','reserve','maintenance','extra','shock','interest','principal','pay','dep','renovationDed','taxable','taxEffect','afterTax','contributions','retained','debt','saleTax','propertyNet','etfNet'];const labels=['Jahr','Kalenderjahr','Hauptmietzins monatlich im Jahresmittel','Mietzinsobergrenze (0 = keine im Jahr)','Einnahmen','Betriebskosten','Rücklage','Instandhaltung','Werbungskosten','Sonderaufwand','Zinsen','Tilgung','Kreditrate','AfA','Renovierungsabzug','Steuergewinn','ESt (+) / Entlastung (-)','Netto-Cashflow','Zuschuss','Cash-Guthaben','Restschuld','ImmoESt','Immo netto','ETF netto'];download(new Blob(['\ufeff'+[labels.join(';'),...results.rows.map(r=>cols.map(k=>String(Math.round(r[k]*100)/100).replace('.',',')).join(';'))].join('\r\n')],{type:'text/csv;charset=utf-8'}),'immo-cashflows.csv')}
function init(){renderInputs();const configs=[['rentShift','Miete ändern','%'],['rateShift','Zins ändern','%-Punkte'],['vacancyShift','Leerstand ändern','%-Punkte'],['costShift','Laufende Kosten ändern','%'],['valueShift','Wertsteigerung ändern','%-Punkte'],['shockCost','Zusätzliche Instandhaltung','€'],['shockYear','Instandhaltung in Jahr','Jahr']];for(const f of configs)$('scenarioInputs').append(field(...f,undefined,custom,scenarios));document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n===b));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===b.dataset.view));$('tooltip').hidden=true;});$('export').onclick=()=>download(new Blob([JSON.stringify({version:5,values:s},null,2)],{type:'application/json'}),'immo-szenario.json');$('csv').onclick=csv;$('detailYear').onchange=()=>{detailYear=+$('detailYear').value;cashDetails()};$('cashUnit').onchange=()=>{unit=$('cashUnit').value;cashDetails()};for(const id of ['axisY','axisX','heatMetric'])$(id).onchange=heatmap;$('reset').onclick=()=>{if(confirm('Eingaben auf Standardwerte zurücksetzen?')){s={...defaults};save();renderInputs();update()}};$('import').onchange=async ev=>{try{const file=ev.target.files?.[0];if(!file)return;const data=JSON.parse(await file.text());if(!data.values||typeof data.values!=='object'||Array.isArray(data.values))throw Error();s=normalize(data.values);save();renderInputs();update()}catch{alert('Ungültige Szenariodatei.')}finally{ev.target.value=''}};document.addEventListener('scroll',hideInputHelp,true);window.addEventListener('resize',hideInputHelp);document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){$('tooltip').hidden=true;hideInputHelp()}});update();}
init();
function renderRentalInputs(){const root=$('rentalInputs');if(!root)return;const active=s.rentalMode!=='market'||s.marketScope!=='outside';root.innerHTML='<h3>Immobilie · Miete & laufende Ausgaben</h3><div id="rentalCommon" class="rental-group group"></div><div class="mrg-toggle-row"><div><strong>Mietrechtsgesetz (MRG)</strong><p class="note">Aktivieren, wenn Voll- oder Teilanwendung vorliegt. „Aus“ setzt einen tatsächlich vom MRG ausgenommenen Vertrag voraus.</p></div><button id="mrgToggle" type="button" role="switch" aria-checked="'+active+'" class="mrg-switch '+(active?'on':'')+'">MRG '+(active?'aktiv':'aus')+'<span aria-hidden="true"></span></button></div><div id="rentalFields" class="inputgrid"></div>';for(const f of groups.find(g=>g[0]==='Vermietung & Ausgaben')[1])$('rentalCommon').append(field(f[0],f[1],f[2],f[3],s,()=>{Object.assign(s,normalize(s));save();update()}));$('mrgToggle').onclick=()=>{if(active){s.mrgChoice=s.rentalMode==='market'?'partial':s.rentalMode;s.rentalMode='market';s.marketScope='outside'}else{s.rentalMode=s.mrgChoice==='partial'?'market':s.mrgChoice;s.marketScope='partial'}save();renderRentalInputs();update()};
let fields=[];if(active){const kind=field('mrgKind','Welche MRG-Regel gilt?',[['wgg15h','Aus Genossenschaft gekauft · § 15h WGG'],['partial','Teilanwendung · freier Hauptmietzins'],['manual','Andere Mietzinsgrenze · geprüft eingeben']],'Die Auswahl konkretisiert den aktivierten MRG-Schutz. Die rechtliche Einordnung anhand von Gebäude, Förderung und Vertrag prüfen.',{mrgKind:s.rentalMode==='market'?'partial':s.rentalMode},()=>{});const select=kind.querySelector('select');select.onchange=()=>{s.rentalMode=select.value==='partial'?'market':select.value;s.mrgChoice=select.value;s.marketScope='partial';save();renderRentalInputs();update()};$('rentalFields').append(kind)}
if(s.rentalMode==='wgg15h')fields.push(
['wggTransfer','Wie wurde erstmals Eigentum begründet?',[['unknown','Bitte auswählen'],['tenant','Kauf durch den bisherigen Mieter'],['tenant_chain','Erwerbskette nach Kauf durch bisherigen Mieter'],['immediate','Sofortiges Eigentum nach §§ 15/15a'],['investor','Direktkauf als Anleger von der Bauvereinigung']],'Der direkte Anlegerkauf ist nicht mit einer nachträglichen Übertragung an den Mieter gleichzusetzen.'],
['publicFunds','Mit öffentlichen Mitteln errichtet / finanziert?',[['unknown','Unbekannt'],['yes','Ja, nachgewiesen'],['no','Nein']]],
['buildingEra','Errichtung des Gebäudes',[['unknown','Unbekannt'],['post1945','Ab 9. Mai 1945'],['pre1945','Vor 9. Mai 1945']]],
['applicationDate','Maßgeblicher Antrag / Verkaufsangebot','Datum','Für die Übergangsregel § 39 Abs. 36 WGG: Datum des maßgeblichen Antrags oder freiwilligen Angebots, nicht der Kaufoptionsbeginn. Ab 1.8.2019.'],
['firstSaleDate','Erster Kaufvertrag mit der Bauvereinigung','Datum','Daran hängt die 15-Jahres-Frist. Bei Weiterverkauf läuft die ursprüngliche Frist weiter.'],
['region','Bundesland',Object.entries(RENT_REGIONS).map(([k,v])=>[k,v.name])],['area','Wohnnutzfläche','m²','Für den Hauptmietzins; keine gesonderten Garagen- oder Stellplatzflächen.'],
['fundingChecked','Weitere Förderungs- und Vertragsbindungen geprüft?',[['no','Noch offen'],['yes','Ja, Vermietung ist zulässig']],'Förderungsrecht, Nutzungsauflagen und Kaufvertrag können zusätzliche oder strengere Vorgaben enthalten.'],
['additionalCap','Strengere zusätzliche Monatsgrenze (0 = keine)','€','Nur Hauptmietzins netto; zusätzliche absolute Grenze nach Abschlägen, ohne Indexsteigerung fortgeführt.']);
if(s.rentalMode==='manual')fields.push(['manualCap','Geprüfte unbefristete Monatsobergrenze','€','Keine automatische Altbau-/Lage-/Kategorieprüfung. Betrag aus einer fallbezogenen Prüfung; der Befristungsabschlag wird hier anschließend noch abgezogen.'],['additionalCap','Weitere absolute Monatsgrenze (0 = keine)','€']);
fields.push(['leaseDate','Neuer Mietvertrag ab (Abschluss = Mietbeginn)','Datum','Leer = 1. Januar des Startjahres. Automatische MRG-Wertsicherung nur für Neuverträge ab 2026. Abschluss und Einzug werden gleichgesetzt. Steuerliche Vermietungsbereitschaft für die AfA wird weiterhin ab Januar unterstellt.'],['leaseFixed','Befristeter Mietvertrag?',[['no','Unbefristet'],['yes','Befristet (25 % Abschlag bei Mietzinsgrenze)']]],['leaseYears','Vereinbarte Befristungsdauer','Jahre'],['landlordBusiness','Vermieterstatus bei Vertragsabschluss',[['private','Kein Unternehmer nach KSchG'],['business','Unternehmer nach KSchG']],'Nicht allein nach „privat“ oder Anzahl der Wohnungen entscheiden; maßgeblich ist der rechtliche Unternehmerstatus.'],['indexation','Wirksame vertragliche Wertsicherung vereinbart?',[['yes','Ja, jährliches VPI-Modell'],['no','Nein, keine Erhöhung']]],['inflationForecast','Angenommene künftige VPI-Jahresinflation','%','Prognose, kein veröffentlichter zukünftiger Wert. Bei MRG: über 3 % zählt der Mehrbetrag nur halb; zusätzliche Deckel 2026/2027.']);if(s.rentalMode!=='market')fields.push(['otherIncomeChecked','Sonstige Einnahmen separat rechtlich geprüft?',[['no','Nein / keine zusätzlichen Einnahmen'],['yes','Ja, eigenständig zulässig']],'Betriebskosten sind hier kein zusätzlicher Gewinn. Ein Möbel-/Nebenentgelt darf die Mietzinsgrenze nicht verdeckt umgehen.']);
const div=document.createElement('div');div.className='group rental-group';for(const f of fields){if(['leaseYears','landlordBusiness'].includes(f[0])&&s.leaseFixed!=='yes')continue;if(['landlordBusiness','inflationForecast'].includes(f[0])&&!active)continue;if(f[0]==='leaseFixed'&&!active)f[2]=[['no','Unbefristet'],['yes','Befristet']];div.append(field(f[0],f[1],f[2],f[3],s,()=>{Object.assign(s,normalize(s));save();if(f[0]==='leaseFixed')renderRentalInputs();update()}))}$('rentalFields').append(div);}
function rentalStatus(){const r=results,plan=r.rental,root=$('rentalStatus'),blocked=!plan.valid;document.querySelector('main').classList.toggle('model-blocked',blocked);$('rentalBlock').hidden=!blocked;$('csv').disabled=blocked;root.className='rental-status '+(blocked?'blocked':'ready');const names={market:s.marketScope==='outside'?'Freier Mietzins außerhalb MRG':'Freier Mietzins · MRG-Teilanwendung',wgg15h:'MRG · Genossenschaftskauf (§ 15h WGG)',manual:'MRG · manuell geprüfte Grenze'};root.innerHTML='<strong>'+names[s.rentalMode]+'</strong>'+(blocked?'<p>Berechnung gesperrt, bis diese Angaben geklärt sind:</p><ul>'+plan.errors.map(t=>'<li>'+t+'</li>').join('')+'</ul>':`<p>Gewünschte Miete: ${eur2(s.rent)} · angesetzter Hauptmietzins bei Vertragsbeginn: <b>${eur2(plan.initialRent)}</b>${plan.initialCap!==null?' · Obergrenze: '+eur2(plan.initialCap):''}${plan.bindingEnd?' · Ende der 15h-Frist: '+plan.bindingEnd:''}.</p>`)+(plan.valid&&plan.initialRent<s.rent?'<p>Die gewünschte Miete überschreitet die Grenze. Cashflow, Steuern und Szenarien verwenden die niedrigere Miete.</p>':'')+plan.warnings.map(t=>'<p>'+t+'</p>').join('')+(plan.valid?'<p class="note">Bei MRG jährliche VPI-Anpassung frühestens April, bei Mietzinsbeschränkung im Modell ab Mai nach rechtzeitiger schriftlicher Mitteilung. Die konkrete Vertragsklausel muss dies erlauben.</p>':'');}
function rentalMethodCards(r){return [
['9 · MRG und Genossenschaftskauf',`Der Modus „MRG: Genossenschaftskauf“ ist auf die nachträgliche Eigentumsübertragung an bisherige Mieter bzw. entsprechende Erwerbsketten zugeschnitten. § 15h WGG setzt öffentliche Mittel voraus. Die Übergangsregel hängt vom maßgeblichen Antrag/Angebot ab 1.8.2019 ab. Die 15 Jahre beginnen mit dem ersten Kaufvertrag, nicht mit späteren Weiterverkäufen. Während dieser Zeit gilt als Monatsgrenze Landesrichtwert × Wohnnutzfläche; bei Befristung × 0,75. Es werden keine Lage-, Balkon- oder sonstigen Zuschläge hinzugerechnet. Unklare Förderungs-, Erwerbs- oder Altbaufälle sperren diese Rechnung. Ein direkter Anlegerkauf kann dauerhaft WGG-gebunden sein und wird hier nicht als 15h-Fall berechnet. Auch nach Fristende erfolgt bei einem laufenden Vertrag kein automatischer Sprung zur Marktmiete. Sonstige MRG-Fälle brauchen eine separat geprüfte Obergrenze.`,r.rental.valid?[['Gewünschter Hauptmietzins',r.p.rent],['Angesetzter Hauptmietzins bei Vertragsbeginn',r.rental.initialRent]]:[]],
['10 · Wertsicherung, Richtwerte und Befristung',`Richtwerte sind für alle Bundesländer bis 1.4.2026 hinterlegt. Spätere Richtwerte sind Prognosen aus deiner VPI-Annahme: 2027 höchstens +2 %, ab 2028 wird bei Inflation über 3 % der Mehrbetrag nur halb berücksichtigt. Neuverträge ab 2026: erste Indexanpassung im Folgejahr, anteilig für volle Monate nach Abschluss. Bei MRG-Mietzinsgrenzen erfolgt die Anpassung im Modell ab Mai, sonst ab April; eine wirksame Klausel und fristgerechte schriftliche Mitteilung werden vorausgesetzt. Die vertragliche Steigerungsgrenze kann Erhöhungen weiter beschränken. Ohne Klausel bleibt die Miete konstant. Mindestbefristung bei MRG: 5 Jahre für Unternehmer, sonst 3 Jahre. Fortsetzungen werden zu gleichen Konditionen unterstellt. Förderungsrecht, konkrete Klauseln, Ansprüche bei einem Verkauf nach §§ 15g/15i WGG und neue Mietvereinbarungen nach Fristablauf werden nicht automatisch beurteilt.`,[]]
];}

function openEtfInfo(){let dialog=$('etfInfo');if(!dialog){dialog=document.createElement('dialog');dialog.id='etfInfo';dialog.setAttribute('aria-labelledby','etfInfoTitle');dialog.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">ORIENTIERUNG FÜR DIE RENDITEEINGABE</div><h2 id="etfInfoTitle">Historische Indexrenditen p. a.</h2></div><button class="outline" id="closeEtfInfo" aria-label="Info schließen">✕</button></div><p>Alle Zeiträume enden am <strong>30. Juni 2026</strong>. Annualisierte Rendite (CAGR) in <strong>Euro · Net Return · ohne Währungsabsicherung</strong>.</p><div class="tablewrap"><table><thead><tr><th>Index · EUR Net Return</th><th>5 Jahre</th><th>10 Jahre</th><th>20 Jahre</th></tr></thead><tbody><tr><td>MSCI World</td><td>≈ 12,4 %</td><td>≈ 12,8 %</td><td>≈ 9,3 %</td></tr><tr><td>S&amp;P 500</td><td>≈ 13,9 %</td><td>≈ 14,6 %</td><td>≈ 11,3 %</td></tr></tbody></table></div><p class="note">Gerundete Orientierungswerte, keine exakte offizielle EUR-Factsheet-Abrechnung. Startdaten: 30.06.2021 · 30.06.2016 · 30.06.2006.</p><p><strong>Net Return</strong> bedeutet: Dividenden werden nach den im Index unterstellten Quellensteuern wiederangelegt. Persönliche österreichische KESt und ETF-Kosten sind noch nicht abgezogen. Euro-Renditen enthalten den Wechselkurseffekt; sie sind keine EUR-Hedged-Renditen.</p><p><strong>CAGR einfach erklärt:</strong> die gleichmäßige Jahresrendite, mit der aus dem Anfangswert der Endwert geworden wäre. Formel: (Endwert / Anfangswert)^(1 / Jahre) − 1. Die tatsächlichen Jahresrenditen schwanken.</p><details class="benchmark-sources"><summary>Quellen und Umrechnung nachvollziehen</summary><p>MSCI World (5/10 Jahre) und S&amp;P 500 (5/10 Jahre): veröffentlichte USD-Net-Return-Indexrenditen bis 30.06.2026 aus den Benchmarktabellen von <a href="https://www.ssga.com/dk/en_gb/intermediary/etfs/spdr-msci-world-ucits-etf-sppw-gy" target="_blank" rel="noopener">State Street · MSCI World</a> und <a href="https://www.ssga.com/dk/en_gb/intermediary/etfs/spdr-sp-500-ucits-etf-acc-spyl-gy" target="_blank" rel="noopener">State Street · S&amp;P 500</a>. MSCI 20 Jahre: 8,7 % USD Net Return aus der <a href="https://www.walterscott.com/strategies/global-equity/global-equity-usd/" target="_blank" rel="noopener">MSCI-Benchmarktabelle von Walter Scott</a>. Anbieter-Seiten werden laufend aktualisiert; hier bleibt der Stichtag fest.</p><p>EUR-Umrechnung: (1 + USD-CAGR) × (USD je EUR am Start / USD je EUR am Ende)^(1 / Jahre) − 1. EZB-Referenzkurse: 30.06.2021 1,1884; 30.06.2016 1,1102; 30.06.2006 1,2713; 30.06.2026 1,1394. Quellen: <a href="https://www.ecb.europa.eu/stats/exchange/eurofxref/shared/pdf/2021/06/20210630.pdf" target="_blank" rel="noopener">EZB 2021</a>, <a href="https://www.ecb.europa.eu/press/annual-reports-financial-statements/wfs/2016/html/fs160706.en.html" target="_blank" rel="noopener">EZB 2016</a>, <a href="https://www.ecb.europa.eu/press/annual-reports-financial-statements/wfs/2006/html/fs060705.en.html" target="_blank" rel="noopener">EZB 2006</a>, <a href="https://eur-lex.europa.eu/eli/C/2026/2951/oj/eng" target="_blank" rel="noopener">EU-Amtsblatt / EZB 2026</a>. Andere Devisen-Fixingzeiten der Indexanbieter können abweichen.</p><p>S&amp;P 500 20 Jahre: ≈ 11,3 % EUR Net Total Return laut <a href="https://signal-alpha.fr/rendement-bourse/" target="_blank" rel="noopener">Signal Alpha, Tabelle per 30.06.2026</a>. Dieser Wert ist eine gerundete Sekundärquellenangabe, keine hier nachgerechnete Anbieter-Zeitreihe. Alle Werte dienen ausschließlich der Orientierung und werden nicht automatisch in die Prognose übernommen.</p></details><p class="note">Vergangene Renditen sind keine Vorhersage.</p><div class="banner-note"><strong>ETF-Steuern in Österreich</strong><p>27,5 % KESt ist der Standardsatz. Zusätzlich zu Ausschüttungen und Verkaufsgewinnen können auch ausschüttungsgleiche Erträge eines thesaurierenden Fonds jährlich steuerpflichtig sein. Die vereinfachte Prognose berechnet diese nicht. Maßgeblich sind die konkreten <a href="https://service.bmf.gv.at/Service/Allg/ivf/AusschErtr/_start_auswahl.asp" target="_blank" rel="noopener">Fonds-/OeKB-Meldedaten</a>.</p></div>`;document.body.append(dialog);$('closeEtfInfo').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()}})}dialog.showModal();}
